dataTableFormat:
{
  "is multi section": "true",
  "search parameters": [
    {
      "parameter": "gene",
      "label": "Gene",
      "type": "input",
      "values": "kp genes"
    }
  ],
  "tab groups": [
    {
      "label": "Gene information",
      "group id": "gene_info",
      "sections": [
        {
          "section": "general_gene_info_function",
          "label": "Gene function"
        },
        {
          "section": "general_gene_info_go",
          "label": "Gene ontology"
        },
        {
          "section": "general_gene_info_pathway",
          "label": "Gene pathways"
        }
      ]
    },
    {
      "label": "GTEx gene information",
      "group id": "gtex_gene_info",
      "sections": [
        {
          "section": "GTEx_gene",
          "label": "GTEx: Tissue specificity"
        },
        {
          "section": "GTEx_gene_kp",
          "label": "GTEx: Gene expression levels"
        }
      ]
    },
    {
      "label": "Gene associations",
      "group id": "human_gene_asso",
      "sections": [
        {
          "section": "huge",
          "label": "Human Genetic Evidence Calculator scores"
        },
        {
          "section": "common_variant",
          "label": "Common variant associations"
        },
        {
          "section": "rare_variant",
          "label": "Rare variant associations"
        }
      ]
    }
  ],
  "sections": [
    {
      "section id": "general_gene_info_function",
      "header": "general_gene_info_function",
      "data point": {
        "type": "api",
        "parameters": [
          "gene"
        ],
        "parameters type": "replace",
        "url": "https://rest.uniprot.org/uniprotkb/search?limit=1&query=(gene_exact:$gene)+AND+(organism_id:9606)+AND+(reviewed:true)&format:json&fields=cc_function",
        "data type": "json",
        "data wrapper": [
          "results",
          0,
          "comments",
          0,
          "texts",
          0
        ]
      },
      "table format": {
        "data convert": [
          {
            "type": "raw",
            "field name": "Evidences",
            "raw field": "evidences"
          },
          {
            "type": "raw",
            "field name": "Function",
            "raw field": "value"
          }
        ],
        "rows as info cards": {
          "key": "Evidences"
        },
        "top rows": [
          "Function"
        ],
        "column formatting": {}
      }
    },
    {
      "section id": "general_gene_info_go",
      "header": "general_gene_info_go",
      "data point": {
        "type": "api",
        "parameters": [
          "gene"
        ],
        "parameters type": "replace",
        "url": "https://mygene.info/v3/query?fields=go&q=$gene",
        "data type": "json",
        "data wrapper": [
          "hits"
        ]
      },
      "table format": {
        "data convert": [
          {
            "type": "data to rows",
            "field name": "GO",
            "raw field": "go",
            "group by": [
              "evidence",
              "gocategory",
              "id",
              "pubmed",
              "qualifier",
              "term"
            ]
          },
          {
            "type": "raw",
            "field name": "evidence",
            "raw field": "evidence"
          },
          {
            "type": "raw",
            "field name": "gocategory",
            "raw field": "gocategory"
          },
          {
            "type": "raw",
            "field name": "id",
            "raw field": "id"
          },
          {
            "type": "raw",
            "field name": "pubmed",
            "raw field": "pubmed"
          },
          {
            "type": "raw",
            "field name": "qualifier",
            "raw field": "qualifier"
          },
          {
            "type": "raw",
            "field name": "term",
            "raw field": "term"
          }
        ],
        "top rows": [
          "evidence",
          "gocategory",
          "id",
          "pubmed",
          "qualifier",
          "term"
        ],
        "column formatting": {}
      }
    },
    {
      "section id": "general_gene_info_pathway",
      "header": "general_gene_info_pathway",
      "data point": {
        "type": "api",
        "parameters": [
          "gene"
        ],
        "parameters type": "replace",
        "url": "https://mygene.info/v3/query?fields=pathway&q=$gene",
        "data type": "json",
        "data wrapper": [
          "hits"
        ]
      },
      "table format": {
        "data convert": [
          {
            "type": "data to rows",
            "field name": "Pathway",
            "raw field": "pathway",
            "group by": [
              "id",
              "name"
            ]
          },
          {
            "type": "raw",
            "field name": "ID",
            "raw field": "id"
          },
          {
            "type": "raw",
            "field name": "Name",
            "raw field": "name"
          },
          {
            "type": "string to array",
            "separate by": ".",
            "take index": 0,
            "field name": "Key",
            "raw field": "_key0"
          }
        ],
        "top rows": [
          "ID",
          "Name",
          "Key"
        ],
        "column formatting": {}
      }
    },
    {
      "section id": "GTEx_gene",
      "header": "GTEx: Gene expression levels and tissue specificity",
      "data point": {
        "type": "api",
        "url": "https://cfde.hugeampkpnbi.org/api/bio/query/gtex-tstat?q=$gene",
        "parameters": [
          "gene"
        ],
        "parameters type": "replace",
        "data type": "bioindex"
      },
      "table format": {
        "data convert": [
          {
            "type": "raw",
            "field name": "Tissue",
            "raw field": "tissue"
          },
          {
            "type": "raw",
            "field name": "Biosample",
            "raw field": "biosample"
          },
          {
            "type": "raw",
            "field name": "Tstat",
            "raw field": "tstat"
          }
        ],
        "top rows": [
          "Tissue",
          "Biosample",
          "Tstat"
        ],
        "column formatting": {
          "Tstat": {
            "type": [
              "scientific notation",
              "render background percent"
            ]
          },
          "Tissue": {
            "type": [
              "link"
            ],
            "link to": "/r/kc_dge_tissue?tissue=",
            "new tab": "true"
          }
        },
        "initial sort by": {
          "field": "Tissue"
        }
      },
      "filters": [
        {
          "field": "Tissue",
          "label": "Tissue",
          "type": "checkbox"
        },
        {
          "field": "Biosample",
          "label": "Biosample",
          "type": "checkbox"
        }
      ],
      "visualizer": {
        "type": "bar plot",
        "label": "P-Value",
        "group by": "Tissue",
        "y axis field": "Tstat",
        "convert y -log10": null,
        "y ticks decimal point": "2",
        "render by": "Biosample",
        "y axis label": "Tstat",
        "x axis label": "Tissue / Biosample",
        "beta field": null,
        "hover content": [
          "Tissue",
          "Tstat"
        ],
        "thresholds": "calculate",
        "thresholds calculate": [
          [
            0.05,
            "/",
            "data length"
          ]
        ],
        "height": 300,
        "plot margin": {
          "top": 200,
          "bottom": 200,
          "left": 150,
          "right": 175
        }
      }
    },
    {
      "section id": "GTEx_gene_kp",
      "header": "GTEx: Gene expression levels and tissue specificity",
      "data point": {
        "type": "api",
        "url": "https://bioindex-dev.hugeamp.org/api/bio/query/gene-expression?q=$gene",
