            "raw field": "tissueId"
          },
          {
            "type": "raw",
            "field name": "Biosample",
            "raw field": "biosample"
          },
          {
            "type": "raw",
            "field name": "Biosample Id",
            "raw field": "biosampleId"
          },
          {
            "type": "raw",
            "field name": "Dataset",
