            "new tab": "true"
          },
          "Biosample Id": {
            "type": [
              "link"
            ],
            "link to": "https://www.ebi.ac.uk/ols4/search?ontology=uberon&q=",
            "new tab": "true"
          }
        }
      },
      "filters": [
        {
          "field": "Tissue",
          "label": "Tissue",
          "type": "checkbox"
        },
        {
          "field": "Biosample",
          "label": "Biosample",
          "type": "checkbox"
        }
      ],
      "visualizer": {
        "type": "box plot",
        "label": "Absolute gene expression",
        "group by": "Tissue",
