        "height": 300,
        "plot margin": {
          "top": 200,
          "bottom": 200,
          "left": 150,
          "right": 175
        }
      },
      "pre filters": [
        {
          "field": "Collection",
          "value": "GTEx",
          "type": "search"
        }
      ]
    },
    {
